import "./styles/skeuo-input.css";
import type { InputHTMLAttributes, TextareaHTMLAttributes } from "react";
export function SkeuoInput({ className = "", ...props }: InputHTMLAttributes<HTMLInputElement>) {
  return <input data-sk-root="" className={`sk-input ${className}`} {...props} />;
}
export function SkeuoTextarea({ className = "", ...props }: TextareaHTMLAttributes<HTMLTextAreaElement>) {
  return <textarea data-sk-root="" className={`sk-input sk-textarea ${className}`} {...props} />;
}

@import "./skeuo-base.css";
.sk-input{ display: block; width: 100%; min-width: 0; padding: 12px 14px; border: 1px solid var(--sk-input-edge); border-radius: 6px; background: var(--sk-well); color: var(--sk-ink); box-shadow: var(--sk-field-shadow); font: inherit; font-size: 13px; line-height: 1.7; }
.sk-input::placeholder{ color: var(--sk-muted); }
.sk-input:focus-visible{ outline: 2px solid var(--sk-ring); outline-offset: 3px; }
.sk-input:disabled{ opacity: .55; cursor: not-allowed; }
.sk-textarea{ min-height: 130px; resize: vertical; }
@media(max-width:600px){.sk-input{ font-size: 16px; }}

.sk-input {font-family:var(--sk-font-sans,system-ui,sans-serif);}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root]:focus-visible,[data-sk-root] :focus-visible) {outline:2px solid var(--sk-ring);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Exact material defaults, with optional host semantic colors. Public host tokens are never written. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper: var(--card, #faf9f5);--sk-album-ink: var(--card-foreground, #45423b);--sk-album-edge: var(--border, #c4c2ba);--sk-album-base: var(--sk-sem-album-base, #d6d4ca);
  --sk-bg: var(--background, #fff); --sk-ink: var(--foreground, #202020); --sk-muted: var(--muted-foreground, #777774); --sk-line: var(--border, #e7e7e4);
  --sk-surface: var(--card, #f5f5f2); --sk-surface-raised: var(--sk-sem-surface-raised, #fafaf8); --sk-well: var(--muted, #e9e9e5);
  --sk-edge: var(--border, #d1d1cb); --sk-highlight: #fff; --sk-base: var(--sk-sem-base, #d9d9d3); --sk-shadow: #00000017;
  --sk-field-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight);
  --sk-accent: var(--primary, #365e50); --sk-accent-bright: var(--sk-sem-accent-bright, #487b68); --sk-accent-base: var(--sk-sem-accent-base, #213c32); --sk-accent-edge: var(--sk-sem-accent-edge, #294b3e); --sk-accent-ink: var(--primary-foreground, #fff);
  --sk-key: var(--secondary, #f9f9f7); --sk-key-edge: var(--border, #c6c7c1); --sk-key-base: var(--sk-sem-key-base, #d0d1ca);
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper: var(--card, #272728);--sk-album-ink: var(--card-foreground, #d0cfca);--sk-album-edge: var(--border, #555456);--sk-album-base: var(--sk-sem-album-base, #111214);
  --sk-bg: var(--background, #000); --sk-ink: var(--foreground, #efefeb); --sk-muted: var(--muted-foreground, #92928d); --sk-line: var(--border, #242424);
  --sk-surface: var(--card, #191919); --sk-surface-raised: var(--sk-sem-surface-raised, #252525); --sk-well: var(--muted, #111);
  --sk-edge: var(--border, #3b3b39); --sk-highlight: #ffffff1e; --sk-base: var(--sk-sem-base, #080808); --sk-shadow: #00000099;
  --sk-field-shadow: inset 0 7px 10px #000000d9,inset 3px 2px 5px #00000099,inset 0 -1px 0 #ffffff14,0 1px 0 #ffffff26,0 -1px 0 #000000b3;
  --sk-accent: var(--primary, #9ab5a6); --sk-accent-bright: var(--sk-sem-accent-bright, #bbcec2); --sk-accent-base: var(--sk-sem-accent-base, #4d6558); --sk-accent-edge: var(--sk-sem-accent-edge, #6f8a79); --sk-accent-ink: var(--primary-foreground, #14251c);
  --sk-key: var(--secondary, #292a29); --sk-key-edge: var(--border, #484946); --sk-key-base: var(--sk-sem-key-base, #101110);

} }

:where(:root,.light,.dark,[data-theme="light"],[data-theme="dark"]) {
  --sk-sem-accent-bright: color-mix(in srgb,var(--primary) 84%,white);
  --sk-sem-accent-base: color-mix(in srgb,var(--primary) 65%,black);
  --sk-sem-accent-edge: color-mix(in srgb,var(--primary) 78%,black);
  --sk-sem-base: color-mix(in srgb,var(--card) 85%,black);
  --sk-sem-surface-raised: color-mix(in srgb,var(--card) 96%,white);
  --sk-sem-key-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-sem-album-base: color-mix(in srgb,var(--card) 83%,black);
  --sk-card-ink: var(--card-foreground,var(--sk-ink));
  --sk-sem-secondary-raised: color-mix(in srgb,var(--secondary) 96%,white);
  --sk-sem-secondary-base: color-mix(in srgb,var(--secondary) 83%,black);
  --sk-secondary: var(--secondary,var(--sk-surface));
  --sk-secondary-ink: var(--secondary-foreground,var(--sk-ink));
  --sk-secondary-raised: var(--sk-sem-secondary-raised,var(--sk-surface-raised));
  --sk-secondary-base: var(--sk-sem-secondary-base,var(--sk-base));
  --sk-input-edge: var(--input,var(--sk-edge));
  --sk-ring: var(--ring,var(--sk-accent));
}
